<style>
.project-hero{padding:58px 0 66px;background:var(--gradient-cool);border-bottom:1px solid var(--border)}.project-crumbs{margin-bottom:30px;color:var(--muted-foreground);font-size:13px}.project-crumbs a{color:inherit}.project-label{display:block;margin-bottom:12px;color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.2em;text-transform:uppercase}.project-hero h1{max-width:900px;margin:0;font-size:clamp(40px,5.6vw,66px);font-weight:800;line-height:1.05}.project-hero p{max-width:760px;margin:18px 0 0;color:var(--muted-foreground);font-size:18px;line-height:1.6}
.project-section{padding:72px 0}.project-intro{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:56px;align-items:start;margin-bottom:42px}.project-intro-label{margin:0;color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.25em;text-transform:uppercase}.project-copy{color:var(--muted-foreground);font-size:18px;line-height:1.75}.project-copy p{margin-top:0}
.project-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.project-photo{margin:0;overflow:hidden;border:1px solid var(--border);border-radius:24px;background:#fff;box-shadow:var(--shadow-soft)}.project-photo img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover;transition:.45s var(--ease)}.project-photo:hover img{transform:scale(1.025)}.project-photo figcaption{padding:15px 18px;color:var(--muted-foreground);font-size:13px}.project-back{display:inline-flex;margin-top:38px;color:var(--primary-deep);font-weight:700}
@media(max-width:760px){.project-hero{padding:44px 0 48px}.project-section{padding:52px 0}.project-intro{grid-template-columns:1fr;gap:14px}.project-grid{grid-template-columns:1fr}.project-copy{font-size:16px}}
</style>
<section class="project-hero"><div class="wrap"><div class="project-crumbs"><a href="/idemaclima/">Home</a> / <a href="/idemaclima/referenze">Referenze</a> / <?= e($reference['title']) ?></div><span class="project-label"><?= e(trim(($reference['location']??'').(!empty($reference['project_year'])?' · '.$reference['project_year']:''))) ?></span><h1><?= e($reference['title']) ?></h1><?php if(!empty($reference['short_description'])): ?><p><?= e($reference['short_description']) ?></p><?php endif; ?></div></section>
<section class="project-section"><div class="wrap"><?php if(!empty($reference['description'])): ?><div class="project-intro"><p class="project-intro-label">— Il progetto</p><div class="project-copy"><?= nl2br(e($reference['description'])) ?></div></div><?php endif; ?><div class="project-grid"><?php foreach($images as $image): ?><figure class="project-photo"><img src="<?= e($image['image_path']) ?>" alt="<?= e($image['alt_text'] ?: $reference['title']) ?>" loading="lazy"><?php if(!empty($image['caption'])): ?><figcaption><?= e($image['caption']) ?></figcaption><?php endif; ?></figure><?php endforeach; ?></div><a class="project-back" href="/idemaclima/referenze">← Torna a tutte le referenze</a></div></section>